# 42_mp_misconduct_seats_forfeited.R
# MP misconduct exposure — criminal convictions + parliamentary-conduct censure
# resignations leading to loss of seat, 1979-2025.
#
# Analytical purpose (Ch3 - The Political Class):
#   Candidate indicator for PJ's own idea (7 Sep session): "number of court cases
#   exposing bad politician behaviour" as a further measure of the political class.
#   HC Library SN04594 ("imprisoned MPs") was checked and rejected as a standalone
#   series (see sources_raw/hc_library_sn04594_imprisoned_members/SOURCE_NOTE.md -
#   dominated by one clustered 1986-91 NI Troubles protest-fine episode, then a
#   28-year gap). This uses Mortimore & Blick's "Seats Forfeited" page instead -
#   PJ, 8 Sep: "mortimoore table is good... as is a consistent measure across time"
#   i.e. take the source's own inclusion logic as-is, one compiler, one page,
#   applied consistently, rather than trying to build a purer composite.
#
# CONSTRUCT: combines the two Mortimore & Blick sub-lists that are genuinely about
#   personal/conduct misconduct (excludes their separate bankruptcy and
#   government-contract sub-lists on that same page, which are procedural, not
#   misconduct):
#     - "criminal_conviction": left/expelled the House after conviction on
#       criminal charges
#     - "censure_resignation": gave up the seat under censure for parliamentary
#       conduct (incl. Standards Committee findings, lobbying-rules breaches)
#
# ⚠ HONEST LIMITATION, not fixed by switching source: this remains a RARE-EVENTS
#   series. 1979-2025 has 11 qualifying events total (see 11 Sep and 12 Sep
#   additions below), all 2009 or later - zero in 1979-2008. This is a
#   *detected and formally sanctioned* misconduct series, not an
#   underlying-behaviour series.
#
# ⚠⚠ CORRECTION, 12 Sep 2026 — N: 10 -> 11, and a THIRD category added. Margaret
#   Ferrier (2023) was missing: breached Covid self-isolation rules Sept 2020,
#   Standards Committee recommended a 30-sitting-day suspension (30 Mar 2023),
#   upheld on appeal by the Independent Expert Panel (22 May 2023, "blatant and
#   deliberate dishonest intent"), forced out via a successful Recall of MPs Act
#   petition (1 Aug 2023) and lost the by-election (5 Oct 2023). She fits
#   NEITHER existing category - not a criminal conviction (cf. Onasanya,
#   Amesbury) and not a voluntary censure resignation (cf. Gibson, Mercer,
#   Paterson, Parish; she contested the process throughout and never resigned)
#   - so a third category, "standards_suspension_recall", was added rather than
#   forcing her into "censure_resignation" and misdescribing the mechanism.
#
# ⚠⚠ CORRECTION, 11 Sep 2026 — robustness pass on Ch3 coding decisions (PJ:
#   "why not get going on these 3.4 and 3.5"). Cross-checking against HC
#   Library SN04594 ("imprisoned members", already checked and rejected as a
#   standalone series 8 Sep — see sources_raw/hc_library_sn04594_imprisoned_
#   members/SOURCE_NOTE.md) surfaced TWO genuine in-window seats-forfeited
#   events that Mortimore & Blick's list missed and this script had therefore
#   also missed:
#   - Fiona Onasanya (2019): perverting the course of justice; removed via the
#     FIRST-EVER successful Recall of MPs Act 2015 petition — verified
#     directly against UK Parliament's own record, not just SN04594's summary.
#   - Mike Amesbury (2025): common assault; resigned under pressure after a
#     suspended sentence — verified directly against the CPS's own press
#     release.
#   Both fit the existing construct exactly (criminal conviction -> loss of
#   seat) and both fall in the 2009+ window, so the headline pattern (zero
#   events 1979-2008, all clustering 2009+) is reinforced, not disrupted, by
#   adding them. N: 8 -> 10. See 67_mp_misconduct_robustness.R for the full
#   sensitivity comparison (with/without regime-shift events, with/without
#   these two additions) run before this correction was made.
#
# ⚠⚠ VERIFIED, 8 Sep (PJ asked directly: is this a change in the law, not real?)
#   TWO real, dated legal changes explain PART of the post-2009 shape - checked
#   against primary/authoritative sources, not assumed:
#   - Parliamentary Standards Act 2009 s.10 created a NEW specific offence (false/
#     misleading info on an MPs' allowances claim, up to 1yr) - before this,
#     prosecuting expenses fraud needed a general Theft Act false-accounting charge.
#   - R v Chaytor [2010] UKSC 52 (1 Dec 2010): three MPs argued parliamentary
#     privilege barred criminal courts from trying them for expenses claims at
#     all. Supreme Court unanimously rejected this - until this ruling, whether
#     courts could even hear such a case was genuinely unsettled.
#   - Recall of MPs Act 2015 (in force Mar 2016): before this, only a sentence
#     OVER 12 months (Forfeiture Act 1870 s.2) automatically forced an MP out.
#     A shorter sentence, a Standards Committee suspension, or an expenses-claim
#     conviction did NOT force a seat vacancy on their own pre-2016.
#   BUT this only covers PART of the 8 events, not all of them:
#   - Illsley (2011) & MacShane (2012), both "false accounting, expenses claims"
#     - sit exactly in the window PSA s.10 + Chaytor opened up. Real candidate
#     artefacts of the legal change, not (only) a behaviour change.
#   - Huhne (2013, perverting the course of justice) & Ahmad Khan (2022, sexual
#     assault) are ORDINARY crimes, prosecutable at any point under general law
#     - same basis as Baker (1954, forgery) or Stonehouse (1976, fraud) earlier
#     in the same source list. No legal-barrier story needed for these two.
#   - The censure-resignation cases (Gibson 2009, Mercer 2014, Paterson 2021,
#     Parish 2022) never depended on criminal prosecution at all - that route
#     (political/Standards pressure forcing resignation) already existed
#     pre-2009 (e.g. Profumo 1963). What's new post-2016 is the recall
#     mechanism giving CONSTITUENTS formal leverage independent of the MP's own
#     party - plausibly raises the rate a Standards finding ends in departure
#     rather than a quiet suspension, but doesn't fabricate the underlying finding.
#   Net: treat the 2 expenses-fraud convictions as regime-shift-confounded: the
#   other 6 events are not explained away by these specific legal changes.
#
# DATA SOURCE: Mortimore & Blick, Butler's British Political Facts (12th edn
#   draft), "Seats Forfeited", pp.47-48. See
#   sources_raw/british_political_facts_12_v5/British Political Facts 12 v5 c04.pdf
#
#   DATA FILE: data/raw/mp_misconduct_seats_forfeited_DATA_ENTRY.csv (full list,
#     1903-2022, all events in the source - this script filters to 1979-2025)
#
# OUTPUT:
#   data/processed/mp_misconduct_annual_1979_2025.csv
#   figures/ch3_misconduct_seats_forfeited.png

if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, ggplot2, readr, tidyr)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT  <- .ROOT
DATA_IN  <- file.path(PROJECT, "data/raw/mp_misconduct_seats_forfeited_DATA_ENTRY.csv")
DATA_OUT <- file.path(PROJECT, "data/processed/mp_misconduct_annual_1979_2025.csv")
FIG_OUT  <- file.path(PROJECT, "figures/ch3_misconduct_seats_forfeited.png")

COL_CRIM <- "#d7191c"
COL_CENS <- "#2166ac"

# ============================================================
# 1. LOAD, FILTER TO 1979-2025
# ============================================================
events_all <- read_csv(DATA_IN, show_col_types = FALSE)
cat(sprintf("Full source list: %d events, %d-%d\n",
            nrow(events_all), min(events_all$year), max(events_all$year)))

events <- events_all |> filter(year >= 1979, year <= 2025)
cat(sprintf("1979-2025 window: %d events\n", nrow(events)))
print(events |> select(year, member, category, reason))

# ============================================================
# 2. ANNUAL COUNT SERIES, ZERO-FILLED 1979-2025
# ============================================================
annual_by_cat <- events |>
  count(year, category, name = "n") |>
  complete(year = 1979:2025,
           category = c("criminal_conviction", "censure_resignation", "standards_suspension_recall"),
           fill = list(n = 0))

annual <- annual_by_cat |>
  group_by(year) |>
  summarise(n_criminal   = sum(n[category == "criminal_conviction"]),
            n_censure    = sum(n[category == "censure_resignation"]),
            n_standards  = sum(n[category == "standards_suspension_recall"]),
            n_total      = sum(n), .groups = "drop") |>
  arrange(year) |>
  mutate(n_cumulative = cumsum(n_total))

write_csv(annual, DATA_OUT)
cat(sprintf("\nSaved: %s\n", DATA_OUT))

cat("\n=== Period totals ===\n")
annual |>
  mutate(period = cut(year, breaks = c(1978, 1988, 1997, 2009, 2019, 2025),
                       labels = c("1979-88", "1989-97", "1998-2009", "2010-19", "2020-25"))) |>
  group_by(period) |>
  summarise(n_events = sum(n_total), .groups = "drop") |>
  print()

cat(sprintf("\nZero-event years: %d of 47 (%.0f%%)\n",
            sum(annual$n_total == 0), 100 * mean(annual$n_total == 0)))
cat(sprintf("First qualifying year: %d\n", min(annual$year[annual$n_total > 0])))

# ============================================================
# 3. FIGURE — event count per year (bar) + cumulative (line), diagnostic style
#    (not a numbered book figure yet - PJ to decide headline/appendix placement)
# ============================================================
plot_df <- annual |>
  select(year, n_criminal, n_censure, n_standards) |>
  pivot_longer(c(n_criminal, n_censure, n_standards), names_to = "category", values_to = "n") |>
  mutate(category = recode(category, n_criminal = "Criminal conviction",
                            n_censure = "Censure resignation",
                            n_standards = "Standards suspension + recall"))

p1 <- ggplot(plot_df, aes(x = year, y = n, fill = category)) +
  geom_col(width = 0.8) +
  scale_fill_manual(values = c("Criminal conviction" = COL_CRIM,
                                "Censure resignation" = COL_CENS,
                                "Standards suspension + recall" = "#4d9221")) +
  scale_x_continuous(limits = c(1978, 2026), breaks = seq(1980, 2025, 5)) +
  scale_y_continuous(breaks = 0:2) +
  labs(title = "MP misconduct events leading to loss of seat, 1979-2025",
       subtitle = "Criminal convictions + parliamentary-conduct censure resignations (Mortimore & Blick)",
       x = NULL, y = "Events", fill = NULL) +
  theme_minimal(base_size = 10) +
  theme(legend.position = "bottom", panel.grid.minor = element_blank())

p2 <- ggplot(annual, aes(x = year, y = n_cumulative)) +
  geom_step(colour = "grey30", linewidth = 0.6) +
  scale_x_continuous(limits = c(1978, 2026), breaks = seq(1980, 2025, 5)) +
  labs(subtitle = "Cumulative count", x = NULL, y = "Cumulative events") +
  theme_minimal(base_size = 10) +
  theme(panel.grid.minor = element_blank())

if (!requireNamespace("patchwork", quietly = TRUE)) pacman::p_load(patchwork)
fig <- p1 / p2 + patchwork::plot_layout(heights = c(2, 1))
ggsave(FIG_OUT, fig, width = 7.5, height = 6, dpi = 200, bg = "white")
cat(sprintf("\nFigure saved: %s\n", FIG_OUT))
